-- CS336 Project 1 - Group 28
-- Step 2: write Preliminary back out to a CSV that is byte-for-byte identical
-- to the original downloaded file (sequence_number blanked back out, original
-- row order restored via ORDER BY sequence_number).
--
-- Run with:  psql -f 02_export_to_csv.sql
-- or from inside psql:  \i 02_export_to_csv.sql
-- Then verify with:  diff hmda_2017_nj_all-records_labels.csv reconstructed.csv
-- (no output means the files are identical)
--
-- NOTES:
-- - \copy is a psql backslash (meta-)command, not plain SQL, so unlike a
--   regular multi-line SQL statement it must be entirely on one line -- psql
--   stops reading it at the first newline. Keep this as a single line.
-- - The source file double-quotes every field, including blank ones (""), so
--   FORCE_QUOTE * is used to quote every output field. FORCE_QUOTE never
--   quotes a NULL, though, so every column is converted with
--   coalesce(col::text, '') -- a blank field becomes an empty string, which
--   FORCE_QUOTE does write as "". The ::text casts don't change any values:
--   integer and numeric columns print exactly as they were parsed.
-- - sequence_number is written back out as '' (blank, as in the original)
--   in its original column position, so the generated key is removed.
-- - The output column list aliases that blank as sequence_number, which
--   shadows the real table column of the same name in ORDER BY, so the sort
--   key is table-qualified as p.sequence_number to restore file order.

\copy (SELECT coalesce(as_of_year::text, '') AS as_of_year, coalesce(respondent_id::text, '') AS respondent_id, coalesce(agency_name::text, '') AS agency_name, coalesce(agency_abbr::text, '') AS agency_abbr, coalesce(agency_code::text, '') AS agency_code, coalesce(loan_type_name::text, '') AS loan_type_name, coalesce(loan_type::text, '') AS loan_type, coalesce(property_type_name::text, '') AS property_type_name, coalesce(property_type::text, '') AS property_type, coalesce(loan_purpose_name::text, '') AS loan_purpose_name, coalesce(loan_purpose::text, '') AS loan_purpose, coalesce(owner_occupancy_name::text, '') AS owner_occupancy_name, coalesce(owner_occupancy::text, '') AS owner_occupancy, coalesce(loan_amount_000s::text, '') AS loan_amount_000s, coalesce(preapproval_name::text, '') AS preapproval_name, coalesce(preapproval::text, '') AS preapproval, coalesce(action_taken_name::text, '') AS action_taken_name, coalesce(action_taken::text, '') AS action_taken, coalesce(msamd_name::text, '') AS msamd_name, coalesce(msamd::text, '') AS msamd, coalesce(state_name::text, '') AS state_name, coalesce(state_abbr::text, '') AS state_abbr, coalesce(state_code::text, '') AS state_code, coalesce(county_name::text, '') AS county_name, coalesce(county_code::text, '') AS county_code, coalesce(census_tract_number::text, '') AS census_tract_number, coalesce(applicant_ethnicity_name::text, '') AS applicant_ethnicity_name, coalesce(applicant_ethnicity::text, '') AS applicant_ethnicity, coalesce(co_applicant_ethnicity_name::text, '') AS co_applicant_ethnicity_name, coalesce(co_applicant_ethnicity::text, '') AS co_applicant_ethnicity, coalesce(applicant_race_name_1::text, '') AS applicant_race_name_1, coalesce(applicant_race_1::text, '') AS applicant_race_1, coalesce(applicant_race_name_2::text, '') AS applicant_race_name_2, coalesce(applicant_race_2::text, '') AS applicant_race_2, coalesce(applicant_race_name_3::text, '') AS applicant_race_name_3, coalesce(applicant_race_3::text, '') AS applicant_race_3, coalesce(applicant_race_name_4::text, '') AS applicant_race_name_4, coalesce(applicant_race_4::text, '') AS applicant_race_4, coalesce(applicant_race_name_5::text, '') AS applicant_race_name_5, coalesce(applicant_race_5::text, '') AS applicant_race_5, coalesce(co_applicant_race_name_1::text, '') AS co_applicant_race_name_1, coalesce(co_applicant_race_1::text, '') AS co_applicant_race_1, coalesce(co_applicant_race_name_2::text, '') AS co_applicant_race_name_2, coalesce(co_applicant_race_2::text, '') AS co_applicant_race_2, coalesce(co_applicant_race_name_3::text, '') AS co_applicant_race_name_3, coalesce(co_applicant_race_3::text, '') AS co_applicant_race_3, coalesce(co_applicant_race_name_4::text, '') AS co_applicant_race_name_4, coalesce(co_applicant_race_4::text, '') AS co_applicant_race_4, coalesce(co_applicant_race_name_5::text, '') AS co_applicant_race_name_5, coalesce(co_applicant_race_5::text, '') AS co_applicant_race_5, coalesce(applicant_sex_name::text, '') AS applicant_sex_name, coalesce(applicant_sex::text, '') AS applicant_sex, coalesce(co_applicant_sex_name::text, '') AS co_applicant_sex_name, coalesce(co_applicant_sex::text, '') AS co_applicant_sex, coalesce(applicant_income_000s::text, '') AS applicant_income_000s, coalesce(purchaser_type_name::text, '') AS purchaser_type_name, coalesce(purchaser_type::text, '') AS purchaser_type, coalesce(denial_reason_name_1::text, '') AS denial_reason_name_1, coalesce(denial_reason_1::text, '') AS denial_reason_1, coalesce(denial_reason_name_2::text, '') AS denial_reason_name_2, coalesce(denial_reason_2::text, '') AS denial_reason_2, coalesce(denial_reason_name_3::text, '') AS denial_reason_name_3, coalesce(denial_reason_3::text, '') AS denial_reason_3, coalesce(rate_spread::text, '') AS rate_spread, coalesce(hoepa_status_name::text, '') AS hoepa_status_name, coalesce(hoepa_status::text, '') AS hoepa_status, coalesce(lien_status_name::text, '') AS lien_status_name, coalesce(lien_status::text, '') AS lien_status, coalesce(edit_status_name::text, '') AS edit_status_name, coalesce(edit_status::text, '') AS edit_status, ''::text AS sequence_number, coalesce(population::text, '') AS population, coalesce(minority_population::text, '') AS minority_population, coalesce(hud_median_family_income::text, '') AS hud_median_family_income, coalesce(tract_to_msamd_income::text, '') AS tract_to_msamd_income, coalesce(number_of_owner_occupied_units::text, '') AS number_of_owner_occupied_units, coalesce(number_of_1_to_4_family_units::text, '') AS number_of_1_to_4_family_units, coalesce(application_date_indicator::text, '') AS application_date_indicator FROM Preliminary p ORDER BY p.sequence_number) TO 'reconstructed.csv' WITH (FORMAT csv, HEADER true, FORCE_QUOTE *)
